def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[r[:] for r in grid]
    cols=[c for c in range(w) if all(grid[r][c]==5 for r in range(h))]
    if cols:
        c=min(cols,key=lambda x:abs(x-w//2))
        for r in range(h):
            for j in range(c+1,w): out[r][j]=0
    else:
        rows=[r for r in range(h) if all(v==5 for v in grid[r])]
        if rows:
            r=min(rows,key=lambda x:abs(x-h//2))
            for i in range(r+1,h): out[i]=[0]*w
    return out

